// The cross-engine harness: a fixed, engine-independent run whose state-hash
// chain must come out identical everywhere the sim can run.
//
// This is the one check that actually proves a re-simulated leaderboard is
// trustworthy. The unit tests prove the sim agrees with ITSELF; this proves V8
// in a browser agrees with V8 in Node, and — once a second engine is wired up —
// that it agrees with SpiderMonkey and JavaScriptCore too. `bin/smoke` runs it
// on both sides and compares.
//
// The input pattern is generated by integer arithmetic rather than a PRNG or a
// table, so the generator itself is as portable as the sim.
import { IN_BRAKE, IN_FLIP, IN_LEAN_L, IN_LEAN_R, IN_THROTTLE } from './consts.ts';
import type { Level } from './level.ts';
import type { BikeSpec } from './spec.ts';
import { createSim } from './sim.ts';

/**
 * Deterministic pseudo-input for frame `f`. Busy on purpose: it must reach
 * throttle, brake, both volt directions and flips, because a code path the
 * pattern never takes is a code path the cross-engine check never covers.
 */
export function crossCheckMask(f: number): number {
  const a = (f * 1103515245 + 12345) & 0x7fffffff;
  return (
    ((a >>> 5) % 7 < 4 ? IN_THROTTLE : 0) |
    ((a >>> 9) % 29 === 0 ? IN_BRAKE : 0) |
    ((a >>> 13) % 11 < 3 ? IN_LEAN_L : 0) |
    ((a >>> 17) % 13 < 3 ? IN_LEAN_R : 0) |
    ((a >>> 21) % 61 === 0 ? IN_FLIP : 0)
  );
}

export interface CrossCheck {
  frames: number;
  /** How many times the bike died or finished and the harness restarted it. */
  runs: number;
  hashEvery: number;
  /** One hash per `hashEvery` frames, in order. */
  hashes: string[];
  final: string;
  ticks: number;
  dead: boolean;
  finished: boolean;
  applesLeft: number;
}

export function crossCheck(level: Level, spec: BikeSpec, frames = 2000, hashEvery = 100): CrossCheck {
  const sim = createSim(level, spec);
  const hashes: string[] = [];
  let runs = 0;
  for (let f = 0; f < frames; f++) {
    // A dead run freezes, and a frozen state hashes the same every frame
    // thereafter — which would make most of the chain prove nothing. Restart
    // instead, so every frame in the window exercises live physics. The restart
    // is a deterministic function of the frame index, so it is as portable as
    // the rest of this.
    if (sim.state.dead || sim.state.finished) {
      runs++;
      sim.reset();
    }
    sim.advance(crossCheckMask(f));
    if ((f + 1) % hashEvery === 0) hashes.push(sim.hash());
  }
  return {
    frames,
    runs,
    hashEvery,
    hashes,
    final: sim.hash(),
    ticks: sim.state.tick,
    dead: sim.state.dead,
    finished: sim.state.finished,
    applesLeft: sim.state.applesLeft,
  };
}
